  const tags = EVERY_TAG_PATTERN.join("|");
  const lineEnd = String.raw`(?:\r?\n|(?:\\r)?\\n)?`;
  return text.replace(new RegExp(String.raw`(?:^[ \t]*)?(?:${tags})[ \t]*${lineEnd}`, "gm"), "");
